
import styles from "./priceRange.module.scss";

const PriceRange = ({
  min = 0,
  max = 50000000,
  minPrice = 0,
  setMinPrice,
  maxPrice = 50000000,
  setMaxPrice,
  step = 100000,
}) => {
  const handleMinChange = (e) => {
    const value = Number(e.target.value);

    if (value <= maxPrice) {
      setMinPrice(value);
    }
  };

  const handleMaxChange = (e) => {
    const value = Number(e.target.value);

    if (value >= minPrice) {
      setMaxPrice(value);
    }
  };

  return (
    <div className={styles.priceRange}>
      <div className={styles.values} aria-live="polite">
        <span>
          {minPrice.toLocaleString("fa-IR")} تومان
        </span>

        <span>
          {maxPrice.toLocaleString("fa-IR")} تومان
        </span>
      </div>

      <div className={styles.slider}>
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={minPrice}
          onChange={handleMinChange}
          className={styles.range}
          aria-label="حداقل قیمت"
          aria-valuetext={`${minPrice.toLocaleString("fa-IR")} تومان`}
        />

        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={maxPrice}
          onChange={handleMaxChange}
          className={styles.range}
          aria-label="حداکثر قیمت"
          aria-valuetext={`${maxPrice.toLocaleString("fa-IR")} تومان`}
        />
      </div>
    </div>
  );
};

export default PriceRange;
